+import { Hono } from "hono";
+import { updateUserRole } from "../services/user-service";
+
+var app = new Hono();
+
+app.put("/api/users/:userId/role", async function (c) {
+  var userId = c.req.param("userId");
+  if (!userId) {
+    return c.json({ error: "userId is required" }, 400);
+  }
+
+  var body: { role?: string };
+  try {
+    body = await c.req.json();
+  } catch {
+    return c.json({ error: "Invalid JSON body" }, 400);
+  }
+
+  var role = body.role;
+  if (!role || typeof role !== "string") {
+    return c.json({ error: "role is required and must be a string" }, 400);
+  }
+
+  try {
+    var result = await updateUserRole(userId, role);
+    return c.json({
+      message: "Role updated successfully",
+      userId: userId,
+      previousRole: result.previousRole,
+      newRole: result.newRole,
+    });
+  } catch (err) {
+    var message = err instanceof Error ? err.message : "Unknown error";
+    if (message.startsWith("User not found") || message.startsWith("Invalid role")) {
+      return c.json({ error: message }, 400);
+    }
+    return c.json({ error: "Internal server error" }, 500);
+  }
+});
+
+export default app;
